    return {
      key: event.shiftKey ? letter : letter.toLowerCase(),
      char,
      ctrl,
    };
  }

  const punctuation = US_LAYOUT[event.code];
  if (punctuation) {
    return { key: punctuation[event.shiftKey ? 1 : 0], char, ctrl };
